def current_user():
    uid = session.get("user_id")
    if not uid:
        return None
    con = db()
    row = con.execute("SELECT * FROM users WHERE id=?", (uid,)).fetchone()
    con.close()
    return row

def login_required(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        if not current_user():
            flash("Inicia sessão para continuar.", "error")
            return redirect(url_for("login"))
        return fn(*args, **kwargs)
    return wrapper

def admin_required(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        u = current_user()
        if not u or u["user_type"] != "admin":
            flash("Área reservada ao administrador.", "error")
            return redirect(url_for("home"))
        return fn(*args, **kwargs)
    return wrapper

def admin_log(action, target_type="", target_id=None, details=""):
    try:
        u = current_user()
        if not u or u["user_type"] != "admin":
            return
        con = db()
        con.execute(
            "INSERT INTO admin_audit_log(admin_id,action,target_type,target_id,details) VALUES(?,?,?,?,?)",
            (u["id"], action, target_type, target_id, details)
        )
        con.commit()
        con.close()
    except sqlite3.Error:
        pass

def notify(user_id, title, message, link=""):
    con = db()
    con.execute(
        "INSERT INTO notifications(user_id,title,message,kind,link) VALUES(?,?,?,?,?)",
        (user_id, title, message, "system", link)
    )
    con.commit()
    con.close()

def trial_info(user):
    if not user:
        return None
    try:
        end = datetime.fromisoformat(user["trial_ends_at"])
        days = max(0, (end.date() - datetime.now().date()).days)
    except Exception:
        days = 0
    return days

def plan_label(plan):
    return PLANS.get(plan, ("Plano", 0))[0]

def safe_next(default="dashboard"):
    nxt = request.args.get("next") or request.form.get("next")
    if nxt and nxt.startswith("/"):
        return nxt
    return url_for(default)


def is_following(follower_id, target_type, target_id):
    con = db()
    row = con.execute(
        "SELECT id FROM follows WHERE follower_id=? AND target_type=? AND target_id=?",
        (follower_id, target_type, target_id)
    ).fetchone()
    con.close()
    return bool(row)

def follower_count(target_type, target_id):
    con = db()
    n = con.execute(
        "SELECT COUNT(*) FROM follows WHERE target_type=? AND target_id=?",
        (target_type, target_id)
    ).fetchone()[0]
    con.close()
    return n

def connection_between(a, b):
    if not a or not b or a == b:
        return None
    con = db()
    row = con.execute("""
        SELECT * FROM connections
        WHERE (requester_id=? AND receiver_id=?)
           OR (requester_id=? AND receiver_id=?)
        ORDER BY id DESC LIMIT 1
    """, (a, b, b, a)).fetchone()
    con.close()
    return row

def target_exists(target_type, target_id):
    con = db()
    if target_type == "person":
        row = con.execute(
            "SELECT id FROM users WHERE id=? AND user_type!='admin'",
            (target_id,)
        ).fetchone()
    elif target_type == "company":
        row = con.execute(
            "SELECT id FROM companies WHERE id=?",
            (target_id,)
        ).fetchone()
    else:
        row = None
    con.close()
    return bool(row)

def is_saved(user_id, target_type, target_id):
    if not user_id:
        return False
    con = db()
    row = con.execute("SELECT id FROM saved_items WHERE user_id=? AND target_type=? AND target_id=?", (user_id, target_type, target_id)).fetchone()
    con.close()
    return bool(row)

def saved_count(user_id):
    if not user_id:
        return 0
    con = db()
    n = con.execute("SELECT COUNT(*) FROM saved_items WHERE user_id=?", (user_id,)).fetchone()[0]
    con.close()
    return n

@app.context_processor
def inject_globals():
    u = current_user()
    unread = 0
    unread_messages = 0
    if u:
        con = db()
        unread = con.execute(
            "SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0",
            (u["id"],)
        ).fetchone()[0]
        try:
            unread_messages = con.execute(
                "SELECT COUNT(*) FROM messages WHERE receiver_id=? AND is_read=0",
                (u["id"],)
            ).fetchone()[0]
        except sqlite3.Error:
            unread_messages = 0
        con.close()
    return {"me": u, "unread": unread, "unread_messages": unread_messages, "trial_days": trial_info(u), "saved_count": saved_count, "is_saved": is_saved, "is_following": is_following}

