@app.route("/publicacoes", methods=["GET","POST"])
def publicacoes():
    if request.method=="POST":
        me=current_user()
        if not me:
            flash("Entra na tua conta para publicar.","error"); return redirect(url_for("login"))
        content=request.form.get("content","").strip()
        if content:
            con=db(); con.execute("INSERT INTO posts(author_id,content) VALUES(?,?)",(me["id"],content)); con.commit(); con.close()
            flash("Publicação criada.","success")
        return redirect(url_for("publicacoes"))
    con=db()
    posts=con.execute("""SELECT p.*,u.name,(SELECT COUNT(*) FROM post_likes l WHERE l.post_id=p.id) likes,(SELECT COUNT(*) FROM comments c WHERE c.post_id=p.id) comments_count FROM posts p JOIN users u ON u.id=p.author_id ORDER BY p.id DESC""").fetchall()
    comments=con.execute("""SELECT c.*,u.name FROM comments c JOIN users u ON u.id=c.user_id ORDER BY c.id ASC""").fetchall()
    con.close()
    comments_by_post={}
    for c in comments:
        comments_by_post.setdefault(c["post_id"],[]).append(c)
    body=render_template_string("""<section class="hero"><span class="eyebrow">COMUNIDADE</span><h1>Publicações</h1><p class="muted">Ideias, conteúdos e descobertas da comunidade.</p></section>
    {% if me %}<div class="card premium-form"><form method="post"><textarea name="content" placeholder="Partilha uma ideia..." required></textarea><button class="btn gold">Publicar</button></form></div><div class="space"></div>{% endif %}
    <div class="grid">{% for p in posts %}<article class="card"><span class="small muted">{{p.created_at}}</span><h3>{{p.name}}</h3><p>{{p.content}}</p>
    <div class="post-actions"><form method="post" action="{{url_for('like_post',pid=p.id)}}"><button class="btn">♡ {{p.likes}}</button></form><span class="small muted">💬 {{p.comments_count}} comentário{% if p.comments_count != 1 %}s{% endif %}</span>{% if me %}<form method="post" action="{{url_for('guardar_item',target_type='post',target_id=p.id)}}"><button class="btn" type="submit">{% if is_saved(me.id,'post',p.id) %}Guardado ✓{% else %}Guardar{% endif %}</button></form>{% endif %}</div>
    {% if comments_by_post.get(p.id) %}<div class="comment-list">{% for c in comments_by_post[p.id] %}<div class="comment-item"><div class="comment-meta"><strong>{{c.name}}</strong><span class="small muted">{{c.created_at}}</span></div><p>{{c.content}}</p>{% if me and me.id == c.user_id %}<form method="post" action="{{url_for('delete_comment',cid=c.id)}}" style="margin-top:7px"><button class="btn" type="submit">Eliminar</button></form>{% endif %}</div>{% endfor %}</div>{% endif %}
    {% if me %}<form class="comment-form" method="post" action="{{url_for('comment_post',pid=p.id)}}"><input name="content" maxlength="1000" placeholder="Escreve um comentário..." required><button class="btn gold" type="submit">Comentar</button></form>{% else %}<p class="small muted" style="margin-top:12px">Entra na tua conta para comentar.</p>{% endif %}
    </article>{% else %}<div class="card empty-state"><span class="big-icon">✦</span><h3>Ainda não há publicações.</h3><p class="muted">A primeira ideia pode começar contigo.</p></div>{% endfor %}</div>""",posts=posts,comments_by_post=comments_by_post,me=current_user())
    return page("Publicações",body)

@app.route("/publicacao/<int:pid>/like",methods=["POST"])
@login_required
def like_post(pid):
    me=current_user(); con=db()
    post=con.execute("SELECT id FROM posts WHERE id=?",(pid,)).fetchone()
    if not post:
        con.close(); flash("Publicação não encontrada.","error"); return redirect(url_for("publicacoes"))
    try:
        con.execute("INSERT INTO post_likes(post_id,user_id) VALUES(?,?)",(pid,me["id"]))
        con.commit()
    except sqlite3.IntegrityError:
        con.execute("DELETE FROM post_likes WHERE post_id=? AND user_id=?",(pid,me["id"])); con.commit()
    con.close()
    return redirect(request.referrer or url_for("publicacoes"))

@app.route("/publicacao/<int:pid>/comentar",methods=["POST"])
@login_required
def comment_post(pid):
    me=current_user()
    content=request.form.get("content","").strip()
    if not content:
        flash("Escreve um comentário antes de enviar.","error")
        return redirect(request.referrer or url_for("publicacoes"))
    if len(content)>1000:
        flash("O comentário é demasiado longo. Usa até 1000 caracteres.","error")
        return redirect(request.referrer or url_for("publicacoes"))
    con=db()
    post=con.execute("SELECT id,author_id FROM posts WHERE id=?",(pid,)).fetchone()
    if not post:
        con.close(); flash("Publicação não encontrada.","error"); return redirect(url_for("publicacoes"))
    con.execute("INSERT INTO comments(post_id,user_id,content) VALUES(?,?,?)",(pid,me["id"],content))
    con.commit(); con.close()
    if post["author_id"] != me["id"]:
        notify(post["author_id"],"Novo comentário","Alguém comentou na tua publicação.",url_for("publicacoes"))
    flash("Comentário publicado.","success")
    return redirect(request.referrer or url_for("publicacoes"))

@app.route("/comentario/<int:cid>/eliminar",methods=["POST"])
@login_required
def delete_comment(cid):
    me=current_user(); con=db()
    comment=con.execute("SELECT id FROM comments WHERE id=? AND user_id=?",(cid,me["id"])).fetchone()
    if comment:
        con.execute("DELETE FROM comments WHERE id=?",(cid,)); con.commit(); flash("Comentário eliminado.","success")
    else:
        flash("Só podes eliminar os teus próprios comentários.","error")
    con.close()
    return redirect(request.referrer or url_for("publicacoes"))

@app.route("/oportunidades", methods=["GET","POST"])
def oportunidades():
    if request.method=="POST":
        me=current_user()
        if not me:
            flash("Entra na tua conta para publicar uma oportunidade.","error"); return redirect(url_for("login"))
        title=request.form.get("title","").strip(); desc=request.form.get("description","").strip()
        if not title or not desc:
            flash("Título e descrição são obrigatórios.","error"); return redirect(url_for("oportunidades"))
        con=db(); company=con.execute("SELECT id FROM companies WHERE owner_id=? ORDER BY id DESC LIMIT 1",(me["id"],)).fetchone()
        con.execute("""INSERT INTO opportunities(owner_id,company_id,title,opportunity_type,category,location,description,contact) VALUES(?,?,?,?,?,?,?,?)""",
                    (me["id"],company["id"] if company else None,title,request.form.get("opportunity_type","Emprego"),request.form.get("category",""),request.form.get("location",""),desc,request.form.get("contact","")))
        con.commit(); con.close(); flash("Oportunidade publicada.","success"); return redirect(url_for("oportunidades"))
