@app.route("/oportunidades/<int:opportunity_id>/candidatar",methods=["POST"])
@login_required
def candidatar_oportunidade(opportunity_id):
    me=current_user(); message=request.form.get("message","").strip(); contact=request.form.get("contact","").strip()
    if not message:
        flash("Escreve uma mensagem antes de enviar.","error"); return redirect(url_for("ver_oportunidade",opportunity_id=opportunity_id))
    if len(message)>1000:
        flash("A mensagem é demasiado longa. Usa até 1000 caracteres.","error"); return redirect(url_for("ver_oportunidade",opportunity_id=opportunity_id))
    con=db(); opp=con.execute("SELECT id,owner_id,title FROM opportunities WHERE id=?",(opportunity_id,)).fetchone()
    if not opp:
        con.close(); flash("Oportunidade não encontrada.","error"); return redirect(url_for("oportunidades"))
    if opp["owner_id"]==me["id"]:
        con.close(); flash("Não podes candidatar-te à tua própria oportunidade.","error"); return redirect(url_for("ver_oportunidade",opportunity_id=opportunity_id))
    exists=con.execute("SELECT id FROM opportunity_applications WHERE opportunity_id=? AND applicant_id=?",(opportunity_id,me["id"])).fetchone()
    if exists:
        con.close(); flash("Já tens uma candidatura para esta oportunidade.","error"); return redirect(url_for("ver_oportunidade",opportunity_id=opportunity_id))
    con.execute("INSERT INTO opportunity_applications(opportunity_id,applicant_id,contact,message) VALUES(?,?,?,?)",(opportunity_id,me["id"],contact,message))
    con.commit(); con.close()
    notify(opp["owner_id"],"Nova candidatura",f"Recebeste uma candidatura para: {opp['title']}.",url_for("ver_candidaturas",opportunity_id=opportunity_id))
    flash("Candidatura enviada com sucesso.","success")
    return redirect(url_for("minhas_candidaturas"))

