    allowed={"Pendente","Em análise","Aceite","Recusada"}
    if status not in allowed:
        flash("Estado inválido.","error"); return redirect(request.referrer or url_for("oportunidades"))
    con=db(); row=con.execute("SELECT a.id,a.applicant_id,a.opportunity_id,o.owner_id,o.title FROM opportunity_applications a JOIN opportunities o ON o.id=a.opportunity_id WHERE a.id=?",(application_id,)).fetchone()
