@app.route("/seguir/<target_type>/<int:target_id>", methods=["POST"])
@login_required
def seguir(target_type, target_id):
    me = current_user()
    if target_type not in ("person", "company") or not target_exists(target_type, target_id):
        flash("Destino não encontrado.", "error")
        return redirect(request.referrer or url_for("explorar"))
    if target_type == "person" and target_id == me["id"]:
        flash("Não podes seguir a tua própria conta.", "error")
        return redirect(request.referrer or url_for("perfil", uid=me["id"]))

    con = db()
    try:
        con.execute(
            "INSERT INTO follows(follower_id,target_type,target_id) VALUES(?,?,?)",
            (me["id"], target_type, target_id)
        )
        con.commit()
        if target_type == "person":
            notify(target_id, "Novo seguidor",
                   f"{me['name']} começou a seguir o teu perfil.",
                   url_for("perfil", uid=me["id"]))
        else:
            owner = con.execute(
                "SELECT owner_id,name FROM companies WHERE id=?", (target_id,)
            ).fetchone()
            if owner:
                notify(owner["owner_id"], "Novo seguidor",
                       f"{me['name']} começou a seguir a empresa {owner['name']}.",
                       url_for("empresa", cid=target_id))
        flash("Agora estás a seguir.", "success")
    except sqlite3.IntegrityError:
        flash("Já estás a seguir este perfil.", "error")
    finally:
        con.close()
    return redirect(request.referrer or url_for("explorar"))

