def project_image_url(image_name):
    if not image_name:
        return ""
    return url_for("uploads", filename=image_name)

def save_project_image(file_obj):
    if not file_obj or not file_obj.filename:
        return ""
    filename = secure_filename(file_obj.filename)
    if not filename:
        return ""
    stamp = datetime.now().strftime("%Y%m%d%H%M%S%f")
    final_name = f"{stamp}_{filename}"
    file_obj.save(PROJECT_DIR / final_name)
    return f"projects/{final_name}"

