        user=con.execute("SELECT id,name,email,user_type,location,bio,skills,services,plan,subscription_status,created_at,trial_ends_at,availability,about,whatsapp,instagram,facebook,portfolio FROM users WHERE id=?",(uid,)).fetchone()
