            posts=con.execute("SELECT id,content,created_at FROM posts WHERE author_id=? ORDER BY id DESC LIMIT 10",(uid,)).fetchall()
            opps=con.execute("SELECT id,title,opportunity_type,category,location,created_at FROM opportunities WHERE owner_id=? ORDER BY id DESC LIMIT 10",(uid,)).fetchall()
