@app.route("/admin/utilizador/<int:uid>/nota", methods=["POST"])
@admin_required
def admin_utilizador_nota(uid):
    note=(request.form.get("note") or "").strip()
    con=db()
    user=con.execute("SELECT id,name,email FROM users WHERE id=?",(uid,)).fetchone()
    if not user:
        con.close(); flash("Utilizador não encontrado.","error"); return redirect(url_for("admin_utilizadores"))
    if not note:
        con.close(); flash("A nota não pode estar vazia.","error"); return redirect(url_for("admin_utilizador",uid=uid))
    u=current_user()
    con.execute("INSERT INTO admin_notes(admin_id,target_user_id,note) VALUES(?,?,?)",(u["id"],uid,note[:1000]))
    con.commit(); con.close()
    admin_log("Adicionou nota administrativa", "user", uid, note[:180])
    flash("Nota administrativa guardada.","success")
    return redirect(url_for("admin_utilizador",uid=uid))

