@app.route("/admin/assinaturas")
@admin_required
def admin_assinaturas():
    con=db(); total=active=trial=expired=cancelled=mrr=0; plan_rows=[]; expiring=[]; events=[]
    try:
        total=con.execute("SELECT COUNT(*) FROM users WHERE user_type!='admin'").fetchone()[0]
        active=con.execute("SELECT COUNT(*) FROM users WHERE user_type!='admin' AND subscription_status='active'").fetchone()[0]
        trial=con.execute("SELECT COUNT(*) FROM users WHERE user_type!='admin' AND subscription_status='trial'").fetchone()[0]
        expired=con.execute("SELECT COUNT(*) FROM users WHERE user_type!='admin' AND subscription_status='expired'").fetchone()[0]
        cancelled=con.execute("SELECT COUNT(*) FROM users WHERE user_type!='admin' AND subscription_status='cancelled'").fetchone()[0]
        mrr=con.execute("SELECT COALESCE(SUM(CASE WHEN subscription_status='active' THEN CASE plan WHEN 'person' THEN 3500 WHEN 'micro' THEN 7500 WHEN 'small' THEN 15000 WHEN 'medium' THEN 60000 WHEN 'large' THEN 75000 ELSE 0 END ELSE 0 END),0) FROM users WHERE user_type!='admin'").fetchone()[0] or 0
        plan_rows=con.execute("SELECT plan,subscription_status,COUNT(*) AS total FROM users WHERE user_type!='admin' GROUP BY plan,subscription_status ORDER BY plan,subscription_status").fetchall()
        expiring=con.execute("SELECT id,name,email,plan,trial_ends_at FROM users WHERE user_type!='admin' AND subscription_status='trial' AND trial_ends_at IS NOT NULL AND trial_ends_at!='' AND datetime(trial_ends_at)<=datetime('now','+7 days') ORDER BY trial_ends_at LIMIT 30").fetchall()
        events=con.execute("SELECT e.action,e.details,e.created_at,u.name AS user_name,a.name AS admin_name FROM subscription_events e JOIN users u ON u.id=e.user_id LEFT JOIN users a ON a.id=e.admin_id ORDER BY e.id DESC LIMIT 40").fetchall()
    except sqlite3.Error: pass
    con.close()
    body=render_template_string("""
    <section class="premium-hero"><span class="eyebrow">GESTÃO COMERCIAL</span><h1>Assinaturas <span class="gold">central.</span></h1><p class="muted">Controlo de planos e testes. O valor mensal é uma projeção dos planos ativos, não pagamentos confirmados.</p></section>
    <div class="stats"><div class="stat"><b>{{total}}</b><br>Contas</div><div class="stat"><b>{{active}}</b><br>Ativas</div><div class="stat"><b>{{trial}}</b><br>Em teste</div><div class="stat"><b>{{expired}}</b><br>Expiradas</div><div class="stat"><b>{{cancelled}}</b><br>Canceladas</div><div class="stat"><b>{{"{:,.0f}".format(mrr).replace(",",".")}}</b><br>Kz/mês projetados</div></div>
    <div class="space"></div><div class="grid"><section class="card"><span class="eyebrow">DISTRIBUIÇÃO</span><h2>Planos e estados</h2><div class="ad-table"><table><thead><tr><th>Plano</th><th>Estado</th><th>Total</th></tr></thead><tbody>{% for r in plan_rows %}<tr><td>{{plan_label(r.plan)}}</td><td>{{r.subscription_status}}</td><td><strong>{{r.total}}</strong></td></tr>{% else %}<tr><td colspan="3">Sem dados.</td></tr>{% endfor %}</tbody></table></div></section><section class="card"><span class="eyebrow">ATENÇÃO</span><h2>Testes a terminar</h2>{% for u in expiring %}<div class="campaign-row"><div><strong>{{u.name}}</strong><div class="small muted">{{u.email}} · {{plan_label(u.plan)}}</div></div><small class="muted">{{u.trial_ends_at}}</small><a class="btn" href="{{url_for('admin_utilizador',uid=u.id)}}">Abrir</a></div>{% else %}<p class="muted">Não há testes a terminar nos próximos 7 dias.</p>{% endfor %}</section></div>
    <div class="space"></div><section class="card"><span class="eyebrow">HISTÓRICO</span><h2>Últimos movimentos</h2>{% for e in events %}<div class="campaign-row"><div><strong>{{e.action}}</strong><div>{{e.user_name}} · {{e.details or "Sem detalhe"}}</div><small class="muted">Admin: {{e.admin_name or "Sistema"}}</small></div><small class="muted">{{e.created_at}}</small></div>{% else %}<p class="muted">Ainda não existem movimentos.</p>{% endfor %}</section><div class="space"></div><a class="btn" href="{{url_for('admin')}}">Voltar à Administração</a>
    """,total=total,active=active,trial=trial,expired=expired,cancelled=cancelled,mrr=mrr,plan_rows=plan_rows,expiring=expiring,events=events,plan_label=plan_label)
    return page("Assinaturas",body)

