@app.route("/guardar/<target_type>/<int:target_id>", methods=["POST"])
@login_required
def guardar_item(target_type, target_id):
    me = current_user()
    allowed = {"opportunity":"opportunities", "post":"posts", "project":"projects"}
    if target_type not in allowed:
        flash("Tipo de item inválido.", "error")
        return redirect(request.referrer or url_for("home"))
    con = db()
    exists = con.execute(f"SELECT id FROM {allowed[target_type]} WHERE id=?", (target_id,)).fetchone()
    if not exists:
        con.close(); flash("Item não encontrado.", "error")
        return redirect(request.referrer or url_for("home"))
    saved = con.execute("SELECT id FROM saved_items WHERE user_id=? AND target_type=? AND target_id=?", (me["id"],target_type,target_id)).fetchone()
    if saved:
        con.execute("DELETE FROM saved_items WHERE id=?", (saved["id"],))
        message = "Removido dos guardados."
    else:
        con.execute("INSERT INTO saved_items(user_id,target_type,target_id) VALUES(?,?,?)", (me["id"],target_type,target_id))
        message = "Guardado para veres depois."
    con.commit(); con.close()
    flash(message, "success")
    return redirect(request.referrer or url_for("guardados"))

