def v3_target_url(target_type, target_id):
    try:
        if target_type == "profile": return url_for("perfil", uid=int(target_id))
        if target_type == "company": return url_for("empresa", cid=int(target_id))
        if target_type == "opportunity": return url_for("ver_oportunidade", opportunity_id=int(target_id))
        if target_type == "project": return url_for("projetos")
        if target_type == "post": return url_for("publicacoes")
    except Exception:
        pass
    return ""

def active_ads(limit=6):
    con = db()
    rows = con.execute("""
        SELECT a.*,c.name campaign_name,u.name owner_name
        FROM advertisements a JOIN campaigns c ON c.id=a.campaign_id
        JOIN users u ON u.id=a.owner_id
        WHERE a.status='Ativa' AND c.status='Ativa'
          AND (c.start_date='' OR c.start_date<=date('now'))
          AND (c.end_date='' OR c.end_date>=date('now'))
        ORDER BY a.id DESC LIMIT ?
    """, (limit,)).fetchall()
    for a in rows:
        con.execute("UPDATE advertisements SET views=views+1,updated_at=CURRENT_TIMESTAMP WHERE id=?", (a["id"],))
        con.execute("INSERT INTO campaign_events(advertisement_id,event_type) VALUES(?,?)", (a["id"],"view"))
    con.commit(); con.close()
    return rows

@app.route("/anunciar", methods=["GET","POST"])
@login_required
def anunciar():
    me = current_user()
    con = db()
    if request.method == "POST":
        name = request.form.get("name","").strip()
        objective = request.form.get("objective","Divulgação").strip() or "Divulgação"
        budget = request.form.get("budget_kz","0").strip()
        start = request.form.get("start_date","").strip()
        end = request.form.get("end_date","").strip()
        title = request.form.get("title","").strip()
        desc = request.form.get("description","").strip()
        target = request.form.get("target","").strip()
        cta = request.form.get("cta_text","Ver agora").strip() or "Ver agora"
        custom_url = request.form.get("target_url","").strip()
        try: budget_i = max(0, int(budget))
        except ValueError: budget_i = 0
        if not name or not title:
            con.close(); flash("Indica o nome da campanha e o título do anúncio.","error")
            return redirect(url_for("anunciar"))
        target_type, target_id = "custom", None
        target_url = custom_url
        if target and ":" in target:
            target_type, raw_id = target.split(":",1)
            try: target_id = int(raw_id); target_url = v3_target_url(target_type,target_id)
            except ValueError: target_type, target_id = "custom", None
        cur = con.execute("INSERT INTO campaigns(owner_id,name,objective,budget_kz,start_date,end_date,status) VALUES(?,?,?,?,?,?,?)",(me["id"],name,objective,budget_i,start,end,"Rascunho"))
        cid = cur.lastrowid
        con.execute("INSERT INTO advertisements(campaign_id,owner_id,title,description,target_type,target_id,target_url,cta_text,status) VALUES(?,?,?,?,?,?,?,?,?)",(cid,me["id"],title,desc,target_type,target_id,target_url,cta,"Rascunho"))
        con.commit(); con.close()
        flash("Campanha criada como rascunho. Revê e ativa quando estiver pronta.","success")
        return redirect(url_for("minhas_campanhas"))
    targets=[]
    for r in con.execute("SELECT id,name FROM companies WHERE owner_id=? ORDER BY id DESC",(me["id"],)).fetchall(): targets.append(("company",r["id"],"🏢 "+r["name"]))
    for r in con.execute("SELECT id,title FROM opportunities WHERE owner_id=? ORDER BY id DESC",(me["id"],)).fetchall(): targets.append(("opportunity",r["id"],"🎯 "+r["title"]))
    for r in con.execute("SELECT id,title FROM projects WHERE owner_id=? ORDER BY id DESC",(me["id"],)).fetchall(): targets.append(("project",r["id"],"💼 "+r["title"]))
    targets.append(("profile",me["id"],"👤 Meu perfil"))
    con.close()
    body=render_template_string("""
    <section class="ad-hero"><span class="eyebrow">V3 • PUBLICIDADE</span><h1>Coloca a tua ideia <span class="gold">em destaque.</span></h1><p class="muted">Cria uma campanha para apresentar o teu negócio, serviço, projeto ou oportunidade dentro do Lab de Ideias.</p></section>
    <div class="card form-card"><h2>Nova campanha</h2><form method="post">
      <div class="ad-form-grid"><div><label>Nome da campanha</label><input name="name" placeholder="Ex.: Lançamento Setembro" required></div><div><label>Objetivo</label><select name="objective"><option>Divulgação</option><option>Gerar contactos</option><option>Apresentar oportunidade</option><option>Promover projeto</option></select></div>
      <div><label>Orçamento (Kz)</label><input type="number" min="0" name="budget_kz" placeholder="Ex.: 25000"></div><div><label>Início</label><input type="date" name="start_date"></div><div><label>Fim</label><input type="date" name="end_date"></div>
      <div class="full"><hr><h3>Peça publicitária</h3></div><div class="full"><label>Título do anúncio</label><input name="title" placeholder="Ex.: Conheça o nosso novo serviço" required></div><div class="full"><label>Descrição</label><textarea name="description" placeholder="Mensagem principal do anúncio..."></textarea></div>
      <div class="full"><label>O que queres promover?</label><select name="target"><option value="">Usar link personalizado</option>{% for typ,tid,label in targets %}<option value="{{typ}}:{{tid}}">{{label}}</option>{% endfor %}</select></div><div><label>Texto do botão</label><input name="cta_text" value="Ver agora"></div><div><label>Link personalizado</label><input name="target_url" placeholder="Opcional"></div></div>
      <button class="btn gold">Criar campanha</button><a class="btn" href="{{url_for('minhas_campanhas')}}">Ver minhas campanhas</a>
    </form></div>
    """,targets=targets)
    return page("Anunciar",body)

