@app.route("/sw.js")
def sw():
    script="""const CACHE='lab-de-ideias-v4';self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.add('/offline')).then(()=>self.skipWaiting()))});self.addEventListener('activate',e=>{e.waitUntil(clients.claim())});self.addEventListener('fetch',e=>{if(e.request.method!=='GET')return;e.respondWith(fetch(e.request).catch(()=>caches.match(e.request).then(r=>r||caches.match('/offline'))))});"""
    return script,200,{"Content-Type":"application/javascript; charset=utf-8","Cache-Control":"no-cache"}

